	dgeequ.ndarray( 3, 3, A, 3 ); // $ExpectError
	dgeequ.ndarray( 3, 3, A, 3, 1 ); // $ExpectError
	dgeequ.ndarray( 3, 3, A, 3, 1, 0 ); // $ExpectError
	dgeequ.ndarray( 3, 3, A, 3, 1, 0, R ); // $ExpectError
	dgeequ.ndarray( 3, 3, A, 3, 1, 0, R, 1 ); // $ExpectError
